use pulldown_cmark::{Options, Parser, html};
fn run(s:&str){
    let mut opts = Options::empty();
    opts.insert(Options::ENABLE_SUBSCRIPT);
    let p = Parser::new_ext(s, opts);
    let mut out = String::new();
    html::push_html(&mut out, p);
    println!("{:?} => {:?}", s, out);
}
fn main(){
    run("~~This ~is~~ stricken.~");
    run("a ~[x](https://x)~");
    run("b ~~[x](https://x)~~");
    run("d ~~x ~[x](https://x)~ x~~");
}
